import assert from 'node:assert/strict';import {normalizeWafer,registerWafer,compareWafers,prepareFabMatrix,WaferFabError} from '../core/wafer_fab_engine.mjs';
const a={id:'A',diameterMm:300,unit:'nm',dies:[{x:0,y:0,value:0},{x:1,y:0,value:2},{x:0,y:1,value:null}]};const b={id:'B',diameterMm:300,unit:'nm',dies:[{x:0,y:0,value:1},{x:0,y:1,value:4},{x:-1,y:0,value:8}]};const c=compareWafers(a,b,{registration:{rotateDeg:-90}});assert.equal(c.cells.find(x=>x.x===0&&x.y===0).delta,1);assert.equal(c.cells.find(x=>x.x===1&&x.y===0).delta,2);assert.equal(c.cells.find(x=>x.x===0&&x.y===1).missingA,true);const m=prepareFabMatrix({rows:['T1'],columns:['A','B'],values:[[0,null]],unit:'nm'});assert.equal(m.cells[0].zero,true);assert.equal(m.cells[0].missing,false);assert.equal(m.cells[1].missing,true);assert.throws(()=>compareWafers(a,{...b,unit:'um'}),WaferFabError);console.log(JSON.stringify({pass:true,registration:true,zeroVsMissing:true,unitMismatchBlocking:true,provenance:true},null,2));
